import{_ as t,a0 as l,w as f,s as d,ao as c,I as n,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 GDB 查看程序的棧空間 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GDB 查看程序的棧空間 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GDB 查看程序的棧空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GDB 查看程序的棧空間 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210517 How to look at the stack with gdb","title":"使用 GDB 查看程序的棧空間","tag":"202107","desc":""},"relativePath":"202107/20210517 How to look at the stack with gdb.md","filePath":"[post].md"}'),o={name:"202107/20210517 How to look at the stack with gdb.md"};function x(r,s,h,g,k,b){const e=l("Link");return f(),d("div",null,[s[24]||(s[24]=c(`<h1 id="使用-gdb-查看程序的棧空間" tabindex="-1">使用 GDB 查看程序的棧空間 <a class="header-anchor" href="#使用-gdb-查看程序的棧空間" aria-label="Permalink to “使用 GDB 查看程序的棧空間”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/05/103738f00boylephggpeyh.jpg" alt=""></p><p>昨天我和一些人在閒聊的時候，他們説他們並不真正瞭解棧是如何工作的，而且也不知道如何去查看棧空間。</p><p>這是一個快速教程，介紹如何使用 GDB 查看 C 程序的棧空間。我認為這對於 Rust 程序來説也是相似的。但我這裏仍然使用 C 語言，因為我發現用它更簡單，而且用 C 語言也更容易寫出錯誤的程序。</p><h3 id="我們的測試程序" tabindex="-1">我們的測試程序 <a class="header-anchor" href="#我們的測試程序" aria-label="Permalink to “我們的測試程序”">​</a></h3><p>這裏是一個簡單的 C 程序，聲明瞭一些變量，從標準輸入讀取兩個字符串。一個字符串在堆上，另一個字符串在棧上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>    char stack_string[10] = &quot;stack&quot;;</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    char *heap_string;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    heap_string = malloc(50);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;Enter a string for the stack: &quot;);</span></span>
<span class="line"><span>    gets(stack_string);</span></span>
<span class="line"><span>    printf(&quot;Enter a string for the heap: &quot;);</span></span>
<span class="line"><span>    gets(heap_string);</span></span>
<span class="line"><span>    printf(&quot;Stack string is: %s\\n&quot;, stack_string);</span></span>
<span class="line"><span>    printf(&quot;Heap string is: %s\\n&quot;, heap_string);</span></span>
<span class="line"><span>    printf(&quot;x is: %d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這個程序使用了一個你可能從來不會使用的極為不安全的函數 <code>gets</code> 。但我是故意這樣寫的。當出現錯誤的時候，你就知道是為什麼了。</p><h3 id="第-0-步-編譯這個程序" tabindex="-1">第 0 步：編譯這個程序 <a class="header-anchor" href="#第-0-步-編譯這個程序" aria-label="Permalink to “第 0 步：編譯這個程序”">​</a></h3><p>我們使用 <code>gcc -g -O0 test.c -o test</code> 命令來編譯這個程序。</p><p><code>-g</code> 選項會在編譯程序中將調式信息也編譯進去。這將會使我們查看我們的變量更加容易。</p><p><code>-O0</code> 選項告訴 gcc 不要進行優化，我要確保我們的 <code>x</code> 變量不會被優化掉。</p><h3 id="第一步-啓動-gdb" tabindex="-1">第一步：啓動 GDB <a class="header-anchor" href="#第一步-啓動-gdb" aria-label="Permalink to “第一步：啓動 GDB”">​</a></h3><p>像這樣啓動 GDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gdb ./test</span></span></code></pre></div><p>它打印出一些 GPL 信息，然後給出一個提示符。讓我們在 <code>main</code> 函數這裏設置一個斷點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) b main</span></span></code></pre></div><p>然後我們就可以運行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) b main</span></span>
<span class="line"><span>Starting program: /home/bork/work/homepage/test</span></span>
<span class="line"><span>Breakpoint 1, 0x000055555555516d in main ()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(gdb) run</span></span>
<span class="line"><span>Starting program: /home/bork/work/homepage/test</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Breakpoint 1, main () at test.c:4</span></span>
<span class="line"><span>4   int main() {</span></span></code></pre></div><p>好了，現在程序已經運行起來了。我們就可以開始查看棧空間了。</p><h3 id="第二步-查看我們變量的地址" tabindex="-1">第二步：查看我們變量的地址 <a class="header-anchor" href="#第二步-查看我們變量的地址" aria-label="Permalink to “第二步：查看我們變量的地址”">​</a></h3><p>讓我們從瞭解我們的變量開始。它們每個都在內存中有一個地址，我們可以像這樣打印出來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) p &amp;x</span></span>
<span class="line"><span>$3 = (int *) 0x7fffffffe27c</span></span>
<span class="line"><span>(gdb) p &amp;heap_string</span></span>
<span class="line"><span>$2 = (char **) 0x7fffffffe280</span></span>
<span class="line"><span>(gdb) p &amp;stack_string</span></span>
<span class="line"><span>$4 = (char (*)[10]) 0x7fffffffe28e</span></span></code></pre></div><p>因此，如果我們查看那些地址的堆棧，那我們應該能夠看到所有的這些變量！</p><h3 id="概念-棧指針" tabindex="-1">概念：棧指針 <a class="header-anchor" href="#概念-棧指針" aria-label="Permalink to “概念：棧指針”">​</a></h3><p>我們將需要使用棧指針，因此我將盡力對其進行快速解釋。</p><p>有一個名為 ESP 的 x86 寄存器，稱為“<ruby>棧指針<rt>stack pointer</rt></ruby>”。 基本上，它是當前函數的棧起始地址。 在 GDB 中，你可以使用 <code>$sp</code> 來訪問它。 當你調用新函數或從函數返回時，棧指針的值會更改。</p><h3 id="第三步-在-main-函數開始的時候-我們查看一下在棧上的變量" tabindex="-1">第三步：在 <code>main</code> 函數開始的時候，我們查看一下在棧上的變量 <a class="header-anchor" href="#第三步-在-main-函數開始的時候-我們查看一下在棧上的變量" aria-label="Permalink to “第三步：在 main 函數開始的時候，我們查看一下在棧上的變量”">​</a></h3><p>首先，讓我們看一下 main 函數開始時的棧。 現在是我們的堆棧指針的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) p $sp</span></span>
<span class="line"><span>$7 = (void *) 0x7fffffffe270</span></span></code></pre></div><p>因此，我們當前函數的棧起始地址是 <code>0x7fffffffe270</code>，酷極了。</p><p>現在，讓我們使用 GDB 打印出當前函數堆棧開始後的前 40 個字（即 160 個字節）。 某些內存可能不是棧的一部分，因為我不太確定這裏的堆棧有多大。 但是至少開始的地方是棧的一部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/40x $sp</span></span>
<span class="line"><span>0x7fffffffe270: 0x00000000  0x00000000  0x55555250  0x00005555</span></span>
<span class="line"><span>0x7fffffffe280: 0x00000000  0x00000000  0x55555070  0x00005555</span></span>
<span class="line"><span>0x7fffffffe290: 0xffffe390  0x00007fff  0x00000000  0x00000000</span></span>
<span class="line"><span>0x7fffffffe2a0: 0x00000000  0x00000000  0xf7df4b25  0x00007fff</span></span>
<span class="line"><span>0x7fffffffe2b0: 0xffffe398  0x00007fff  0xf7fca000  0x00000001</span></span>
<span class="line"><span>0x7fffffffe2c0: 0x55555169  0x00005555  0xffffe6f9  0x00007fff</span></span>
<span class="line"><span>0x7fffffffe2d0: 0x55555250  0x00005555  0x3cae816d  0x8acc2837</span></span>
<span class="line"><span>0x7fffffffe2e0: 0x55555070  0x00005555  0x00000000  0x00000000</span></span>
<span class="line"><span>0x7fffffffe2f0: 0x00000000  0x00000000  0x00000000  0x00000000</span></span>
<span class="line"><span>0x7fffffffe300: 0xf9ce816d  0x7533d7c8  0xa91a816d  0x7533c789</span></span></code></pre></div><p>我已粗體顯示了 <code>stack_string</code>，<code>heap_string</code> 和 <code>x</code> 變量的位置，並改變了顏色：</p><ul><li><code>x</code> 是紅色字體，並且起始地址是 <code>0x7fffffffe27c</code></li><li><code>heap_string</code> 是藍色字體，起始地址是 <code>0x7fffffffe280</code></li><li><code>stack_string</code> 是紫色字體，起始地址是 <code>0x7fffffffe28e</code></li></ul><p>你可能會在這裏注意到的一件奇怪的事情是 <code>x</code> 的值是 0x5555，但是我們將 <code>x</code> 設置為 <code>10</code>！ 那是因為直到我們的 <code>main</code> 函數運行之後才真正設置 <code>x</code> ，而我們現在才到了 <code>main</code> 最開始的地方。</p><h3 id="第三步-運行到第十行代碼後-再次查看一下我們的堆棧" tabindex="-1">第三步：運行到第十行代碼後，再次查看一下我們的堆棧 <a class="header-anchor" href="#第三步-運行到第十行代碼後-再次查看一下我們的堆棧" aria-label="Permalink to “第三步：運行到第十行代碼後，再次查看一下我們的堆棧”">​</a></h3><p>讓我們跳過幾行，等待變量實際設置為其初始化值。 到第 10 行時，<code>x</code> 應該設置為 <code>10</code>。</p><p>首先我們需要設置另一個斷點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) b test.c:10</span></span>
<span class="line"><span>Breakpoint 2 at 0x5555555551a9: file test.c, line 11.</span></span></code></pre></div><p>然後繼續執行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) continue</span></span>
<span class="line"><span>Continuing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Breakpoint 2, main () at test.c:11</span></span>
<span class="line"><span>11      printf(&quot;Enter a string for the stack: &quot;);</span></span></code></pre></div><p>好的！ 讓我們再來看看堆棧裏的內容！ <code>gdb</code> 在這裏格式化字節的方式略有不同，實際上我也不太關心這些（LCTT 譯註:可以查看 GDB 手冊中 <code>x</code> 命令，可以指定 <code>c</code> 來控制輸出的格式）。 這裏提醒一下你，我們的變量在棧上的位置：</p><ul><li><code>x</code> 是紅色字體，並且起始地址是 <code>0x7fffffffe27c</code></li><li><code>heap_string</code> 是藍色字體，起始地址是 <code>0x7fffffffe280</code></li><li><code>stack_string</code> 是紫色字體，起始地址是 <code>0x7fffffffe28e</code></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/80x $sp</span></span>
<span class="line"><span>0x7fffffffe270:  0x00  0x00  0x00  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe278:  0x50  0x52  0x55  0x55  0x0a  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe280:  0xa0  0x92  0x55  0x55  0x55  0x55  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe288:  0x70  0x50  0x55  0x55  0x55  0x55  0x73  0x74</span></span>
<span class="line"><span>0x7fffffffe290:  0x61  0x63  0x6b  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe298:  0x00  0x80  0xf7  0x8a  0x8a  0xbb  0x58  0xb6</span></span>
<span class="line"><span>0x7fffffffe2a0:  0x00  0x00  0x00  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2a8:  0x25  0x4b  0xdf  0xf7  0xff  0x7f  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2b0:  0x98  0xe3  0xff  0xff  0xff  0x7f  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2b8:  0x00  0xa0  0xfc  0xf7  0x01  0x00  0x00  0x00</span></span></code></pre></div><p>在繼續往下看之前，這裏有一些有趣的事情要討論。</p><h3 id="stack-string-在內存中是如何表示的" tabindex="-1"><code>stack_string</code> 在內存中是如何表示的 <a class="header-anchor" href="#stack-string-在內存中是如何表示的" aria-label="Permalink to “stack_string 在內存中是如何表示的”">​</a></h3><p>現在（第 10 行），<code>stack_string</code> 被設置為字符串<code>stack</code>。 讓我們看看它在內存中的表示方式。</p><p>我們可以像這樣打印出字符串中的字節（LCTT 譯註：可以通過 <code>c</code> 選項直接顯示為字符）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/10x stack_string</span></span>
<span class="line"><span>0x7fffffffe28e: 0x73    0x74    0x61    0x63    0x6b    0x00    0x00    0x00</span></span>
<span class="line"><span>0x7fffffffe296: 0x00    0x00</span></span></code></pre></div><p><code>stack</code> 是一個長度為 5 的字符串，相對應 5 個 ASCII 碼- <code>0x73</code>、<code>0x74</code>、<code>0x61</code>、<code>0x63</code> 和 <code>0x6b</code>。<code>0x73</code> 是字符 <code>s</code> 的 ASCII 碼。 <code>0x74</code> 是 <code>t</code> 的 ASCII 碼。等等...</p><p>同時我們也使用 <code>x/1s</code> 可以讓 GDB 以字符串的方式顯示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/1s stack_string</span></span>
<span class="line"><span>0x7fffffffe28e: &quot;stack&quot;</span></span></code></pre></div><h3 id="heap-string-與-stack-string-有何不同" tabindex="-1"><code>heap_string</code> 與 <code>stack_string</code> 有何不同 <a class="header-anchor" href="#heap-string-與-stack-string-有何不同" aria-label="Permalink to “heap_string 與 stack_string 有何不同”">​</a></h3><p>你已經注意到了 <code>stack_string</code> 和 <code>heap_string</code> 在棧上的表示非常不同：</p><ul><li><code>stack_string</code> 是一段字符串內容（<code>stack</code>）</li><li><code>heap_string</code> 是一個指針，指向內存中的某個位置</li></ul><p>這裏是 <code>heap_string</code> 變量在內存中的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0xa0  0x92  0x55  0x55  0x55  0x55  0x00  0x00</span></span></code></pre></div><p>這些字節實際上應該是從右向左讀：因為 x86 是小端模式，因此，<code>heap_string</code> 中所存放的內存地址 <code>0x5555555592a0</code></p><p>另一種方式查看 <code>heap_string</code> 中存放的內存地址就是使用 <code>p</code> 命令直接打印 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) p heap_string</span></span>
<span class="line"><span>$6 = 0x5555555592a0 &quot;&quot;</span></span></code></pre></div><h3 id="整數-x-的字節表示" tabindex="-1">整數 x 的字節表示 <a class="header-anchor" href="#整數-x-的字節表示" aria-label="Permalink to “整數 x 的字節表示”">​</a></h3><p><code>x</code> 是一個 32 位的整數，可由 <code>0x0a 0x00 0x00 0x00</code> 來表示。</p><p>我們還是需要反向來讀取這些字節（和我們讀取 <code>heap_string</code> 需要反過來讀是一樣的），因此這個數表示的是 <code>0x000000000a</code> 或者是 <code>0x0a</code>，它是一個數字 <code>10</code>;</p><p>這就讓我把把 <code>x</code> 設置成了 <code>10</code>。</p><h3 id="第四步-從標準輸入讀取" tabindex="-1">第四步：從標準輸入讀取 <a class="header-anchor" href="#第四步-從標準輸入讀取" aria-label="Permalink to “第四步：從標準輸入讀取”">​</a></h3><p>好了，現在我們已經初始化我們的變量，我們來看一下當這段程序運行的時候，棧空間會如何變化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf(&quot;Enter a string for the stack: &quot;);</span></span>
<span class="line"><span>gets(stack_string);</span></span>
<span class="line"><span>printf(&quot;Enter a string for the heap: &quot;);</span></span>
<span class="line"><span>gets(heap_string);</span></span></code></pre></div><p>我們需要設置另外一個斷點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) b test.c:16</span></span>
<span class="line"><span>Breakpoint 3 at 0x555555555205: file test.c, line 16.</span></span></code></pre></div><p>然後繼續執行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) continue</span></span>
<span class="line"><span>Continuing.</span></span></code></pre></div><p>我們輸入兩個字符串，為棧上存儲的變量輸入 <code>123456789012</code> 並且為在堆上存儲的變量輸入 <code>bananas</code>;</p><h3 id="讓我們先來看一下-stack-string-這裏有一個緩存區溢出" tabindex="-1">讓我們先來看一下 <code>stack_string</code>（這裏有一個緩存區溢出） <a class="header-anchor" href="#讓我們先來看一下-stack-string-這裏有一個緩存區溢出" aria-label="Permalink to “讓我們先來看一下 stack_string（這裏有一個緩存區溢出）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/1s stack_string</span></span>
<span class="line"><span>0x7fffffffe28e: &quot;123456789012&quot;</span></span></code></pre></div><p>這看起來相當正常，對嗎？我們輸入了 <code>12345679012</code>，然後現在它也被設置成了 <code>12345679012</code>（LCTT 譯註：實測 gcc 8.3 環境下，會直接段錯誤）。</p><p>但是現在有一些很奇怪的事。這是我們程序的棧空間的內容。有一些紫色高亮的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0x7fffffffe270:  0x00  0x00  0x00  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe278:  0x50  0x52  0x55  0x55  0x0a  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe280:  0xa0  0x92  0x55  0x55  0x55  0x55  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe288:  0x70  0x50  0x55  0x55  0x55  0x55  0x31  0x32</span></span>
<span class="line"><span>0x7fffffffe290:  0x33  0x34  0x35  0x36  0x37  0x38  0x39  0x30</span></span>
<span class="line"><span>0x7fffffffe298:  0x31  0x32  0x00  0x8a  0x8a  0xbb  0x58  0xb6</span></span>
<span class="line"><span>0x7fffffffe2a0:  0x00  0x00  0x00  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2a8:  0x25  0x4b  0xdf  0xf7  0xff  0x7f  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2b0:  0x98  0xe3  0xff  0xff  0xff  0x7f  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe2b8:  0x00  0xa0  0xfc  0xf7  0x01  0x00  0x00  0x00</span></span></code></pre></div><p>令人奇怪的是 <strong><code>stack_string</code> 只支持 10 個字節</strong>。但是現在當我們輸入了 13 個字符以後，發生了什麼？</p><p>這是一個典型的緩衝區溢出，<code>stack_string</code> 將自己的數據寫在了程序中的其他地方。在我們的案例中，這還沒有造成問題，但它會使你的程序崩潰，或者更糟糕的是，使你面臨非常糟糕的安全問題。</p><p>例如，假設 <code>stack_string</code> 在內存裏的位置剛好在 <code>heap_string</code> 之前。那我們就可能覆蓋 <code>heap_string</code> 所指向的地址。我並不確定 <code>stack_string</code> 之後的內存裏有一些什麼。但我們也許可以用它來做一些詭異的事情。</p><h3 id="確實檢測到了有緩存區溢出" tabindex="-1">確實檢測到了有緩存區溢出 <a class="header-anchor" href="#確實檢測到了有緩存區溢出" aria-label="Permalink to “確實檢測到了有緩存區溢出”">​</a></h3><p>當我故意寫很多字符的時候：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> ./test</span></span>
<span class="line"><span>Enter a string for the stack: 01234567891324143</span></span>
<span class="line"><span>Enter a string for the heap: adsf</span></span>
<span class="line"><span>Stack string is: 01234567891324143</span></span>
<span class="line"><span>Heap string is: adsf</span></span>
<span class="line"><span>x is: 10</span></span>
<span class="line"><span>*** stack smashing detected ***: terminated</span></span>
<span class="line"><span>fish: Job 1, &#39;./test&#39; terminated by signal SIGABRT (Abort)</span></span></code></pre></div><p>這裏我猜是 <code>stack_string</code> 已經到達了這個函數棧的底部，因此額外的字符將會被寫在另一塊內存中。</p><p>當你故意去使用這個安全漏洞時，它被稱為“堆棧粉碎”，而且不知何故有東西在檢測這種情況的發生。</p><p>我也覺得這很有趣，雖然程序被殺死了，但是當緩衝區溢出發生時它不會立即被殺死——在緩衝區溢出之後再運行幾行代碼，程序才會被殺死。 好奇怪！</p><p>這些就是關於緩存區溢出的所有內容。</p><h3 id="現在我們來看一下-heap-string" tabindex="-1">現在我們來看一下 <code>heap_string</code> <a class="header-anchor" href="#現在我們來看一下-heap-string" aria-label="Permalink to “現在我們來看一下 heap_string”">​</a></h3><p>我們仍然將 <code>bananas</code> 輸入到 <code>heap_string</code> 變量中。讓我們來看一下內存中的樣子。</p><p>這是在我們讀取了字符串以後，<code>heap_string</code> 在棧空間上的樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/40x $sp</span></span>
<span class="line"><span>0x7fffffffe270:  0x00  0x00  0x00  0x00  0x00  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe278:  0x50  0x52  0x55  0x55  0x0a  0x00  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe280:  0xa0  0x92  0x55  0x55  0x55  0x55  0x00  0x00</span></span>
<span class="line"><span>0x7fffffffe288:  0x70  0x50  0x55  0x55  0x55  0x55  0x31  0x32</span></span>
<span class="line"><span>0x7fffffffe290:  0x33  0x34  0x35  0x36  0x37  0x38  0x39  0x30</span></span></code></pre></div><p>需要注意的是，這裏的值是一個地址。並且這個地址並沒有改變，但是我們來看一下指向的內存上的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/10x 0x5555555592a0</span></span>
<span class="line"><span>0x5555555592a0: 0x62    0x61    0x6e    0x61    0x6e    0x61    0x73    0x00</span></span>
<span class="line"><span>0x5555555592a8: 0x00    0x00</span></span></code></pre></div><p>看到了嗎，這就是字符串 <code>bananas</code> 的字節表示。這些字節並不在棧空間上。他們存在於內存中的堆上。</p><h3 id="堆和棧到底在哪裏" tabindex="-1">堆和棧到底在哪裏？ <a class="header-anchor" href="#堆和棧到底在哪裏" aria-label="Permalink to “堆和棧到底在哪裏？”">​</a></h3><p>我們已經討論過棧和堆是不同的內存區域，但是你怎麼知道它們在內存中的位置呢？</p><p>每個進程都有一個名為 <code>/proc/$PID/maps</code> 的文件，它顯示了每個進程的內存映射。 在這裏你可以看到其中的棧和堆。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/24963/maps</span></span>
<span class="line"><span>... lots of stuff omitted ...</span></span>
<span class="line"><span>555555559000-55555557a000 rw-p 00000000 00:00 0                          [heap]</span></span>
<span class="line"><span>... lots of stuff omitted ...</span></span>
<span class="line"><span>7ffffffde000-7ffffffff000 rw-p 00000000 00:00 0                          [stack]</span></span></code></pre></div><p>需要注意的一件事是，這裏堆地址以 <code>0x5555</code> 開頭，棧地址以 <code>0x7fffff</code> 開頭。 所以很容易區分棧上的地址和堆上的地址之間的區別。</p><h3 id="像這樣使用-gdb-真的很有幫助" tabindex="-1">像這樣使用 gdb 真的很有幫助 <a class="header-anchor" href="#像這樣使用-gdb-真的很有幫助" aria-label="Permalink to “像這樣使用 gdb 真的很有幫助”">​</a></h3><p>這有點像旋風之旅，雖然我沒有解釋所有內容，但希望看到數據在內存中的實際情況可以使你更清楚地瞭解堆棧的實際情況。</p><p>我真的建議像這樣來把玩一下 gdb —— 即使你不理解你在內存中看到的每一件事，我發現實際上像這樣看到我程序內存中的數據會使抽象的概念，比如“棧”和“堆”和“指針”更容易理解。</p><h3 id="更多練習" tabindex="-1">更多練習 <a class="header-anchor" href="#更多練習" aria-label="Permalink to “更多練習”">​</a></h3><p>一些關於思考棧的後續練習的想法（沒有特定的順序）：</p>`,105)),n("ul",null,[s[5]||(s[5]=n("li",null,[a("嘗試將另一個函數添加到 "),n("code",null,"test.c"),a(" 並在該函數的開頭創建一個斷點，看看是否可以從 "),n("code",null,"main"),a(" 中找到堆棧！ 他們説當你調用一個函數時“堆棧會變小”，你能在 gdb 中看到這種情況嗎？")],-1)),s[6]||(s[6]=n("li",null,"從函數返回一個指向棧上字符串的指針，看看哪裏出了問題。 為什麼返回指向棧上字符串的指針是不好的？",-1)),s[7]||(s[7]=n("li",null,"嘗試在 C 中引起堆棧溢出，並嘗試通過在 gdb 中查看堆棧溢出來準確理解會發生什麼！",-1)),s[8]||(s[8]=n("li",null,"查看 Rust 程序中的堆棧並嘗試找到變量！",-1)),n("li",null,[s[1]||(s[1]=a("在 ",-1)),i(e,{href:"https://github.com/guyinatuxedo/nightmare"},{default:p(()=>[...s[0]||(s[0]=[a("噩夢課程",-1)])]),_:1}),s[2]||(s[2]=a(" 中嘗試一些緩衝區溢出挑戰。每個問題的答案寫在 README 文件中，因此如果你不想被寵壞，請避免先去看答案。 所有這些挑戰的想法是給你一個二進制文件，你需要弄清楚如何導致緩衝區溢出以使其打印出 ",-1)),s[3]||(s[3]=n("code",null,"flag",-1)),s[4]||(s[4]=a(" 字符串。",-1))])]),s[25]||(s[25]=n("hr",null,null,-1)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2021/05/17/how-to-look-at-the-stack-in-gdb/"},{default:p(()=>[...s[9]||(s[9]=[a("https://jvns.ca/blog/2021/05/17/how-to-look-at-the-stack-in-gdb/",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("作者：",-1)),i(e,{href:"https://jvns.ca/"},{default:p(()=>[...s[11]||(s[11]=[a("Julia Evans",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),i(e,{href:"https://github.com/amwps290"},{default:p(()=>[...s[13]||(s[13]=[a("amwps290",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const C=t(o,[["render",x]]);export{y as __pageData,C as default};
